import {useMutation, useSuspenseQuery} from "@tanstack/react-query";

import {EntryList} from "./-local/entry-list";
import {fetchEntries, postEntry} from "./entry-api";

export const EntriesPage = () => {
  const {data: responseEntries} = useSuspenseQuery({
    queryKey: ["entries"],
    queryFn: fetchEntries,
    select: ({entries, total}) => ({
      items: entries.map((entry) => ({id: entry.id, label: entry.title.trim()})),
      meta: {total},
    }),
  });
  const {mutate: mutationCreateEntry} = useMutation({mutationFn: postEntry});

  return (
    <EntryList
      items={responseEntries.items}
      total={responseEntries.meta.total}
      onCreate={mutationCreateEntry}
    />
  );
};
